export function translateSeedExerciseName(name: string, t: (text: string) => string): string {
  return isSeedExerciseName(name) ? t(name) : name;
}

export function translatePlanDayName(name: string, t: (text: string, values?: Record<string, string | number>) => string): string {
  if (name === 'Treino livre') return t(name);
  const weekdays = ['Domingo', 'Segunda', 'Terça', 'Quarta', 'Quinta', 'Sexta', 'Sábado'];
  if (weekdays.includes(name)) return t(name);
  const numberedDay = /^Dia (\d+)$/.exec(name);
  return numberedDay ? t('Dia {{number}}', { number: numberedDay[1] }) : name;
}

interface LocaleContextValue {
  locale: Locale;
  setLocale: (locale: Locale) => void;
  t: (text: string, values?: Record<string, string | number>) => string;
  dateLocale: string;
}

const LocaleContext = createContext<LocaleContextValue | null>(null);

function isLocale(value: string | null): value is Locale {
  return value != null && (LOCALES as readonly string[]).includes(value);
}

export function LocaleProvider({ children }: { children: React.ReactNode }) {
  const [locale, setLocaleState] = useState<Locale>(() => {
    const saved = localStorage.getItem(LOCALE_KEY);
    return isLocale(saved) ? saved : 'pt-PT';
  });

  const setLocale = (next: Locale) => {
    localStorage.setItem(LOCALE_KEY, next);
    setLocaleState(next);
  };

  useEffect(() => {
    document.documentElement.lang = locale;
  }, [locale]);

  const value = useMemo<LocaleContextValue>(() => ({
    locale,
    setLocale,
    dateLocale: locale === 'pt-PT' ? 'pt-PT' : locale,
    t: (text, values) => {
      let translated = catalogs[locale][text] ?? extraCatalogs[locale][text] ?? seedExerciseTranslations[locale][text] ?? text;
      if (values) {
        for (const [key, value] of Object.entries(values)) {
          translated = translated.replaceAll(`{{${key}}}`, String(value));
        }
      }
      return translated;
    },
  }), [locale]);

  return <LocaleContext.Provider value={value}>{children}</LocaleContext.Provider>;
}

export function useTranslation() {
  const context = useContext(LocaleContext);
  if (!context) throw new Error('useTranslation must be used within LocaleProvider');
  return context;
}
